{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Ipratropium bromide, a quaternary ammonium antimuscarinic with a permanent positive charge, has absolute oral bioavailability of only about 2% in healthy volunteers; the query also contains a quaternary ammonium [N@+] moiety, making this a direct and high-transfer analogue supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Physostigmine, an N-methylated indole alkaloid with multiple polar groups, has mean absolute oral bioavailability of 3% as an oral solution, showing that related alkaloid scaffolds with favorable small-molecule properties can still have F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, a bridged-ring opioid with an N-methyl basic nitrogen, has mean oral bioavailability of 18% in healthy subjects, below the 20% threshold, supporting low F for the query's similar N-methyl bridged amine architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nitrendipine, despite near-complete gastrointestinal absorption, has absolute oral bioavailability of 10.7 ± 4.7% in humans due to extensive first-pass metabolism and intestinal efflux, illustrating that favorable absorption properties do not ensure F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lisuride, an ergoline-related alkaloid with an indole system and N-methyl groups, has oral bioavailability of 10% ± 7% in humans, supporting low F for the query's indoline-containing polycyclic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "One ipratropium study reported about 32% oral absorption at a 30 mg dose, but this is an outlier against multiple consistent absolute bioavailability measurements of 2-3% and does not outweigh the strong low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium-containing polycyclic alkaloid. The closest high-transfer analogue, ipratropium bromide, also a quaternary ammonium, has absolute oral bioavailability of only ~2-3% in humans. Multiple other high-transfer alkaloid/heterocyclic analogues (physostigmine, pentazocine, nitrendipine, lisuride) show F below 20% due to poor absorption or first-pass metabolism. The physicochemical prior favoring high F is outweighed by this consistent experimental evidence, so F < 20% is predicted.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the query molecule; prediction relies on transferable analogues.",
    "The exact identity and ionization state of the query in vivo are uncertain; if the quaternary ammonium is not present in the administered form, absorption could be more favorable.",
    "Specific contributions of first-pass metabolism, intestinal efflux, or active secretion for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

